        disable_search_indexing: { name: 'Søgning sat til Manuel', description: 'Sætter tjenesten Windows Search til manuel start.' },
        disable_memory_compression: { name: 'Hukommelseskomprimering fra', description: 'Slår komprimering af hukommelse fra. OK med 32+ GB RAM.' },
        disable_copilot: { name: 'Copilot fra', description: 'Slår Windows Copilot og dets ikon på proceslinjen fra.' },
        disable_onedrive_autostart: { name: 'OneDrive-autostart fra', description: 'Forhindrer OneDrive i at starte automatisk med systemet.' },
        disable_activity_history: { name: 'Aktivitetshistorik fra', description: 'Slår indsamling af brugerens aktivitetshistorik fra.' },
