        disable_clipboard_sync: { name: 'Synkronisering af udklipsholder fra', description: 'Slår synkronisering af udklipsholderen mellem enheder fra.' },
        disable_windows_tips: { name: 'Windows-tips fra', description: 'Slår tips og forslag i Windows fra.' },
        disable_auto_driver_updates: { name: 'Automatiske driveropdateringer fra', description: 'Forhindrer Windows Update i automatisk at installere drivere.' },
        enable_gpu_scheduling: { name: 'GPU-planlægning til', description: 'Slår hardwareaccelereret GPU-planlægning (HAGS) til. Til gamere med nyere grafikkort.' },
