        disable_wpbt: { name: 'WPBT (automatisk injektion fra UEFI) fra', description: 'Blokerer WPBT — en UEFI-mekanisme, der lader hardwareproducenter installere software i det skjulte ved hver opstart. Anbefales på OEM-hardware.' },
        detailed_bsod: { name: 'Detaljeret BSOD', description: 'Viser tekniske detaljer (stopkode og parametre) på den blå skærm i stedet for kun det triste ansigt — hjælper med at diagnosticere nedbrud.' },
