        disable_bing_search: { name: 'Απενεργοποίηση Bing στην αναζήτηση', description: 'Απενεργοποιεί τα αποτελέσματα Bing στο μενού Έναρξη και στην αναζήτηση.' },
        disable_edge_background: { name: 'Απενεργοποίηση Edge στο παρασκήνιο', description: 'Απενεργοποιεί την εκτέλεση του Edge στο παρασκήνιο και το Startup Boost.' },
        classic_context_menu: { name: 'Κλασικό μενού δεξιού κλικ', description: 'Επαναφέρει το παλιό μενού περιβάλλοντος στα Windows 11.' },
