        enable_gpu_scheduling: { name: 'Ενεργοποίηση χρονοπρογραμματισμού GPU', description: 'Ενεργοποιεί τον χρονοπρογραμματισμό GPU με επιτάχυνση υλικού (HAGS). Για παίκτες με νεότερες κάρτες γραφικών.' },
