        disable_search_highlights: { name: 'Απενεργοποίηση Search Highlights', description: 'Απενεργοποιεί τα στιγμιότυπα και τις προτάσεις στην Αναζήτηση των Windows.' },
        disable_spotlight: { name: 'Απενεργοποίηση Windows Spotlight', description: 'Απενεργοποιεί το Spotlight στην οθόνη κλειδώματος. Σκοτεινό φόντο αντί για διαφημίσεις.' },
        disable_shared_experiences: { name: 'Απενεργοποίηση κοινόχρηστων εμπειριών', description: 'Απενεργοποιεί τις κοινόχρηστες εμπειρίες και την κοινή χρήση μεταξύ συσκευών.' },
        disable_error_reporting: { name: 'Απενεργοποίηση Windows Error Reporting', description: 'Απενεργοποιεί την αναφορά σφαλμάτων στη Microsoft.' },
        disable_remote_assistance: { name: 'Απενεργοποίηση απομακρυσμένης βοήθειας', description: 'Απενεργοποιεί την απομακρυσμένη βοήθεια. Ασφάλεια + απόρρητο.' },
        disable_background_apps: { name: 'Απενεργοποίηση εφαρμογών παρασκηνίου', description: 'Αποτρέπει την εκτέλεση εφαρμογών UWP στο παρασκήνιο.' },
        disable_startup_delay: { name: 'Απενεργοποίηση καθυστέρησης εκκίνησης', description: 'Καταργεί την καθυστέρηση κατά την εκκίνηση των προγραμμάτων αυτόματης εκκίνησης.' },
        disable_recall: { name: 'Απενεργοποίηση Windows Recall', description: 'Απενεργοποιεί το Windows Recall (στιγμιότυπα οθόνης AI). Απόρρητο.' },
        disable_lock_screen_ads: { name: 'Απενεργοποίηση διαφημίσεων στην οθόνη κλειδώματος', description: 'Απενεργοποιεί τις διαφημίσεις και τις προτάσεις στην οθόνη κλειδώματος.' },
        disable_mouse_acceleration: { name: 'Απενεργοποίηση επιτάχυνσης ποντικιού', description: 'Απενεργοποιεί την επιτάχυνση του ποντικιού στο σύστημα. Για παίκτες.' },
        disable_storage_sense: { name: 'Απενεργοποίηση Λειτουργίας αποθήκευσης', description: 'Απενεργοποιεί τη Λειτουργία αποθήκευσης (Storage Sense) — τα Windows δεν θα διαγράφουν πλέον αυτόματα αρχεία από τα Downloads/Temp ούτε θα αδειάζουν τον Κάδο Ανακύκλωσης βάσει χρονοδιαγράμματος.' },
        disable_wpbt: { name: 'Απενεργοποίηση WPBT (αυτόματη έγχυση UEFI)', description: 'Αποκλείει το WPBT — έναν μηχανισμό UEFI που επιτρέπει στους κατασκευαστές υλικού να εγχέουν σιωπηλά λογισμικό σε κάθε εκκίνηση. Συνιστάται σε υλικό OEM.' },
        detailed_bsod: { name: 'Λεπτομερής BSOD', description: 'Εμφανίζει τεχνικές λεπτομέρειες (κωδικό διακοπής και παραμέτρους) στη μπλε οθόνη αντί για το λυπημένο προσωπάκι — βοηθά στη διάγνωση των σφαλμάτων.' },
        disable_notifications: { name: 'Απενεργοποίηση ειδοποιήσεων', description: 'Κατά περίπτωση: απενεργοποιεί όλες τις ειδοποιήσεις (toasts) και το κέντρο ειδοποιήσεων. Χρήσιμο σε μηχανήματα headless/AI· σε έναν κανονικό υπολογιστή θα χάσετε τις ειδοποιήσεις των εφαρμογών.' },
        ipv4_preferred: { name: 'Προτίμηση IPv4 έναντι IPv6', description: 'Κατά περίπτωση: ορίζει προτίμηση του IPv4 έναντι του IPv6 (χωρίς πλήρη απενεργοποίηση του IPv6). Χρησιμοποιήστε το μόνο όταν αντιμετωπίζετε προβλήματα δικτύου ή αργό DNS μέσω IPv6.' },
        disable_mpo: { name: 'Απενεργοποίηση MPO (διόρθωση τρεμοπαίγματος)', description: 'Κατά περίπτωση: απενεργοποιεί το Multiplane Overlay (MPO). Χρησιμοποιήστε το μόνο αν παρατηρείτε τρεμόπαιγμα, μαύρες αναλαμπές ή ατέλειες στην οθόνη — ενδέχεται να απενεργοποιήσει και το VRR/FreeSync.' },
        verbose_logon: { name: 'Αναλυτικά μηνύματα σύνδεσης', description: 'Εμφανίζει μηνύματα "Έναρξη υπηρεσιών…/Εφαρμογή ρυθμίσεων…" κατά την εκκίνηση και τον τερματισμό αντί για τον κενό δείκτη αναμονής — βοηθά να δείτε πού κολλάει το σύστημα.' },
        disable_fso: { name: 'Απενεργοποίηση βελτιστοποιήσεων πλήρους οθόνης', description: 'Απενεργοποιεί τις βελτιστοποιήσεις πλήρους οθόνης — πολλά παιχνίδια εκτελούνται τότε σε αποκλειστική λειτουργία πλήρους οθόνης (μικρότερη καθυστέρηση εισόδου, καλύτερο alt-tab). Το αποτέλεσμα διαφέρει ανά παιχνίδι, αλλά είναι ασφαλές.' },
        battery_percentage: { name: 'Ποσοστό μπαταρίας στη γραμμή εργασιών', description: 'Εμφανίζει το ποσοστό της μπαταρίας στη γραμμή εργασιών. Χρήσιμο σε φορητούς υπολογιστές.' },
        numlock_on_boot: { name: 'NumLock ενεργό κατά την εκκίνηση', description: 'Ενεργοποιεί αυτόματα το NumLock κατά την εκκίνηση και στην οθόνη σύνδεσης — τέλος στο απενεργοποιημένο NumLock μετά από κάθε επανεκκίνηση.' },
        disable_lockscreen: { name: 'Απενεργοποίηση οθόνης κλειδώματος', description: 'Κατά περίπτωση: καταργεί τη διακοσμητική οθόνη κλειδώματος (ταπετσαρία πριν από το πεδίο κωδικού πρόσβασης) — μεταβαίνετε απευθείας στη σύνδεση. Δεν απενεργοποιεί τον ίδιο τον κωδικό πρόσβασης.' },
        no_password_on_wake: { name: 'Χωρίς κωδικό πρόσβασης μετά την αφύπνιση', description: 'Κατά περίπτωση: μετά την αφύπνιση από την αναστολή λειτουργίας, τα Windows δεν θα ζητούν εκ νέου σύνδεση — επιστρέφετε απευθείας στο σύστημα.' },
