        show_file_extensions: { name: 'Mostrar extensiones de archivo', description: 'Muestra las extensiones de archivo en el Explorador.' },
        show_hidden_files: { name: 'Mostrar archivos ocultos', description: 'Muestra archivos y carpetas ocultos.' },
        explorer_this_pc: { name: 'Explorador: Este equipo', description: 'Abre el Explorador en Este equipo en lugar de Acceso rápido.' },
