        amd_power_profile_high: { name: 'AMD-virtaprofiili: High Performance', description: 'Asettaa AMD-näytönohjaimen virtaprofiiliksi High Performance, jolloin kuristusta on vähemmän ja kellotaajuudet ovat vakaammat. Vain AMD/Radeon-näytönohjaimet.' },
