        amd_power_profile_high: { name: 'AMD energiaprofil: nagy teljesítmény', description: 'Az AMD GPU energiaprofilját nagy teljesítményre állítja a kevesebb visszafojtás és stabilabb órajelek érdekében. Csak AMD/Radeon GPU-k esetén.' },
