        disable_wpbt: { name: 'WPBT (UEFI automatikus injektálás) kikapcsolása', description: 'Letiltja a WPBT-t — egy UEFI-mechanizmust, amely lehetővé teszi a hardvergyártóknak, hogy minden indításkor csendben szoftvert juttassanak a rendszerbe. OEM hardveren ajánlott.' },
        detailed_bsod: { name: 'Részletes BSOD', description: 'A kék képernyőn a szomorú arc helyett technikai részleteket (leállási kód és paraméterek) jelenít meg — segít az összeomlások diagnosztizálásában.' },
