        ipv4_preferred: { name: 'IPv4 előnyben részesítése IPv6-tal szemben', description: 'Helyzetfüggő: az IPv4-et részesíti előnyben az IPv6-tal szemben (az IPv6 teljes kikapcsolása nélkül). Csak hálózati problémák vagy lassú IPv6-os DNS esetén használja.' },
        disable_mpo: { name: 'MPO kikapcsolása (villogás javítása)', description: 'Helyzetfüggő: kikapcsolja a Multiplane Overlay (MPO) funkciót. Csak villogás, fekete villanások vagy képhibák esetén használja — a VRR/FreeSync funkciót is kikapcsolhatja.' },
        verbose_logon: { name: 'Részletes bejelentkezési üzenetek', description: 'Indításkor és leállításkor az üres forgó jel helyett „Szolgáltatások indítása…/Beállítások alkalmazása…” üzeneteket jelenít meg — így látható, hol akad el a rendszer.' },
        disable_fso: { name: 'Teljes képernyős optimalizálás kikapcsolása', description: 'Kikapcsolja a teljes képernyős optimalizálást — sok játék ilyenkor kizárólagos teljes képernyős módban fut (kisebb bemeneti késleltetés, jobb Alt+Tab). A hatás játékonként eltér, de biztonságos.' },
