        disable_game_dvr: { name: 'Game DVR disattivato', description: 'Disabilita la registrazione delle partite in sottofondo (Game Bar/DVR).' },
        amd_disable_enhanced_sync: { name: 'AMD Enhanced Sync disattivato', description: 'Disabilita AMD Enhanced Sync (sincronizzazione dei fotogrammi). Consigliato con monitor FreeSync — in tal caso è inutile. Senza FreeSync, è possibile lasciarlo attivato se lo strappo dell\'immagine vi disturba. Solo GPU AMD/Radeon.' },
        amd_disable_radeon_chill: { name: 'Radeon Chill disattivato', description: 'Disabilita Radeon Chill (limitazione dinamica degli FPS per il risparmio energetico). Disattivato = fluidità totale e meno input lag nei giochi. Solo GPU AMD/Radeon.' },
        amd_power_profile_high: { name: 'Profilo energetico AMD: Prestazioni elevate', description: 'Imposta il profilo energetico GPU AMD su Prestazioni elevate per meno throttling e frequenze più stabili. Solo GPU AMD/Radeon.' },
        disable_gpu_energy_driver: { name: 'GPU Energy Driver disattivato', description: 'Disabilita il servizio GpuEnergyDrv che monitora il consumo energetico della GPU in sottofondo. Piccolo guadagno di prestazioni, funziona con qualsiasi GPU.' },
        nvidia_disable_telemetry: { name: 'Telemetria NVIDIA disattivata', description: 'Disabilita la telemetria e l\'invio di dati dei driver NVIDIA (opt-out). Solo GPU NVIDIA/GeForce/RTX.' },
        disable_telemetry: { name: 'Telemetria disattivata', description: 'Disabilita l\'invio di dati di telemetria a Microsoft.' },
        disable_cortana: { name: 'Cortana disattivata', description: 'Disabilita Cortana e la sua telemetria.' },
