        show_hidden_files: { name: 'Mostra file nascosti', description: 'Mostra file e cartelle nascosti.' },
        explorer_this_pc: { name: 'Esplora risorse: Questo PC', description: 'Apre Esplora risorse su Questo PC invece di Accesso rapido.' },
