        amd_power_profile_high: { name: 'Profil napájania AMD: Vysoký výkon', description: 'Nastaví profil napájania GPU AMD na Vysoký výkon pre menšie obmedzovanie (throttling) a stabilnejšie frekvencie. Iba pre GPU AMD/Radeon.' },
