        disable_sysmain: { name: 'Izklop SysMain', description: 'Izklopi Superfetch/SysMain. Na SSD ni potreben, na HDD ga je bolje pustiti vklopljenega.' },
        disable_xbox_services: { name: 'Izklop storitev Xbox', description: 'Izklopi storitve Xbox (XblAuthManager, XblGameSave, XboxGipSvc, XboxNetApiSvc).' },
        disable_search_indexing: { name: 'Iskanje na ročni zagon', description: 'Nastavi storitev Windows Search na ročni zagon.' },
        disable_memory_compression: { name: 'Izklop stiskanja pomnilnika', description: 'Izklopi stiskanje pomnilnika. Primerno pri 32+ GB RAM.' },
