        enable_gpu_scheduling: { name: 'Vklop razporejanja GPU', description: 'Omogoči strojno pospešeno razporejanje GPU (HAGS). Za igralce z novejšimi grafičnimi karticami.' },
        disable_transparency: { name: 'Izklop prosojnosti', description: 'Izklopi učinke prosojnosti v vmesniku. Rahlo izboljša zmogljivost.' },
        disable_search_highlights: { name: 'Izklop poudarkov iskanja', description: 'Izklopi poudarke in predloge v iskanju Windows.' },
        disable_spotlight: { name: 'Izklop Windows Spotlight', description: 'Izklopi Spotlight na zaklenjenem zaslonu. Temno ozadje namesto oglasov.' },
        disable_shared_experiences: { name: 'Izklop deljenih izkušenj', description: 'Izklopi deljene izkušnje in deljenje med napravami.' },
