        disable_remote_assistance: { name: 'Izklop oddaljene pomoči', description: 'Izklopi oddaljeno pomoč. Varnost in zasebnost.' },
        disable_background_apps: { name: 'Izklop aplikacij v ozadju', description: 'Prepreči izvajanje aplikacij UWP v ozadju.' },
        disable_startup_delay: { name: 'Izklop zakasnitve zagona', description: 'Odstrani zakasnitev pri zagonu programov ob zagonu sistema.' },
        disable_recall: { name: 'Izklop Windows Recall', description: 'Izklopi Windows Recall (posnetki zaslona z AI). Zasebnost.' },
        disable_lock_screen_ads: { name: 'Izklop oglasov na zaklenjenem zaslonu', description: 'Izklopi oglase in predloge na zaklenjenem zaslonu.' },
        disable_mouse_acceleration: { name: 'Izklop pospeševanja miške', description: 'Izklopi sistemsko pospeševanje miške. Za igralce.' },
        disable_storage_sense: { name: 'Izklop Storage Sense', description: 'Izklopi Storage Sense — Windows ne bo več samodejno brisal datotek iz map Downloads/Temp ali po urniku praznil koša.' },
        disable_wpbt: { name: 'Izklop WPBT (samodejno vstavljanje UEFI)', description: 'Blokira WPBT — mehanizem UEFI, ki proizvajalcem strojne opreme omogoča, da ob vsakem zagonu neopazno vstavijo programsko opremo. Priporočeno na strojni opremi OEM.' },
        detailed_bsod: { name: 'Podroben BSOD', description: 'Na modrem zaslonu namesto samo žalostnega obraza prikaže tehnične podrobnosti (koda napake in parametri) — pomaga pri diagnosticiranju sesutij.' },
        disable_notifications: { name: 'Izklop obvestil', description: 'Situacijsko: izklopi vsa obvestila (pojavna obvestila) in središče za obvestila. Uporabno na računalnikih brez zaslona/za AI; na običajnem računalniku boste izgubili obvestila aplikacij.' },
        ipv4_preferred: { name: 'Prednost IPv4 pred IPv6', description: 'Situacijsko: nastavi prednost IPv4 pred IPv6 (brez popolnega izklopa IPv6). Uporabite samo ob težavah z omrežjem ali počasnem DNS prek IPv6.' },
        disable_mpo: { name: 'Izklop MPO (odpravi utripanje)', description: 'Situacijsko: izklopi Multiplane Overlay (MPO). Uporabite samo, če opazite utripanje, črne bliske ali artefakte na zaslonu — lahko izklopi tudi VRR/FreeSync.' },
        verbose_logon: { name: 'Podrobna sporočila ob prijavi', description: 'Ob zagonu in zaustavitvi prikaže sporočila »Zaganjanje storitev …/Uveljavljanje nastavitev …« namesto prazne vrtavke — pomaga ugotoviti, kje se sistem zatakne.' },
        disable_fso: { name: 'Izklop optimizacij celozaslonskega načina', description: 'Izklopi optimizacije celozaslonskega načina — številne igre se nato izvajajo v izključnem celozaslonskem načinu (manjša vhodna zakasnitev, boljši alt-tab). Učinek se razlikuje od igre do igre, vendar je varno.' },
