        disable_lockscreen: { name: 'Izklop zaklenjenega zaslona', description: 'Situacijsko: odstrani okrasni zaklenjeni zaslon (ozadje pred poljem za geslo) — takoj pridete do prijave. Samega gesla ne izklopi.' },
