        detailed_bsod: { name: 'Докладний BSOD', description: 'Показує на синьому екрані технічні подробиці (стоп-код і параметри) замість лише сумного смайлика — допомагає діагностувати збої.' },
        disable_notifications: { name: 'Сповіщення: вимк.', description: 'Ситуативно: вимикає всі сповіщення (спливні) і центр сповіщень. Корисно на headless/AI-машинах; на звичайному ПК ви втратите сповіщення застосунків.' },
        ipv4_preferred: { name: 'Перевага IPv4 над IPv6', description: 'Ситуативно: надає перевагу IPv4 над IPv6 (без повного вимкнення IPv6). Використовуйте лише за проблем із мережею або повільного DNS через IPv6.' },
        disable_mpo: { name: 'MPO: вимк. (усунення мерехтіння)', description: 'Ситуативно: вимикає Multiplane Overlay (MPO). Використовуйте лише, якщо спостерігаєте мерехтіння, чорні спалахи або артефакти на екрані — може також вимкнути VRR/FreeSync.' },
