function currentLanguage() {
    return (typeof getCurrentLang === 'function') ? getCurrentLang() : 'pl';
}

function tweakText(tweak, field) {
    const lang = currentLanguage();
    const langMap = TWEAK_TEXT[lang] || (lang !== 'pl' ? TWEAK_TEXT.en : null);
    return (langMap && langMap[tweak.id] && langMap[tweak.id][field]) || tweak[field] || '';
}

function translateStateMessage(message) {
    if (!message || currentLanguage() === 'pl') return message || '';
    let msg = String(message);
    const replacements = [
        [/^Aktywny$/i, 'Active'],
        [/^Komponent usunięty z systemu$/i, 'Component removed from the system'],
        [/^Brak reguły sprawdzania$/i, 'No check rule'],
        [/Nie znaleziono wartości w output/gi, 'Value not found in output'],
        [/Wynik nie zawiera/gi, 'Output does not contain'],
        [/Wynik/gi, 'Output'],
        [/uruchom launcher jako administrator/gi, 'run the launcher as administrator']
    ];
    replacements.forEach(([from, to]) => { msg = msg.replace(from, to); });
    return msg;
}
